import{_ as o,C as i,o as a,c as r,a2 as t,b as d,w as s,a as h,E as l,a3 as c}from"./chunks/framework.76ZGnlPi.js";const f=JSON.parse('{"title":"Seat Management","description":"","frontmatter":{},"headers":[],"relativePath":"admin/seat-management/index.md","filePath":"admin/seat-management/index.md"}'),p={name:"admin/seat-management/index.md"};function g(u,e,m,k,b,A){const n=i("Mermaid");return a(),r("div",null,[e[1]||(e[1]=t('<h1 id="seat-management" tabindex="-1">Seat Management <a class="header-anchor" href="#seat-management" aria-label="Permalink to &quot;Seat Management&quot;">​</a></h1><p>Admin endpoints for viewing a booking&#39;s seat map and moving a passenger to another seat, on behalf of a customer.</p><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /api/v1/admin/ota/bookings/:id/seat-map</code></td><td><code>bookings:read</code></td><td>Seat map for every segment, plus the seats the booking holds</td></tr><tr><td><code>PATCH /api/v1/admin/ota/bookings/:id/seat</code></td><td><code>bookings:modify</code></td><td>Move one passenger to one seat on one segment</td></tr></tbody></table><p>Both permissions already exist. Seat handling is treated as a booking modification rather than a capability of its own, so no role needs a new grant.</p><p>Unlike the customer routes, these are not scoped to a booking owner - an admin may act on any booking.</p><hr><h2 id="what-an-agent-needs-to-know" tabindex="-1">What an agent needs to know <a class="header-anchor" href="#what-an-agent-needs-to-know" aria-label="Permalink to &quot;What an agent needs to know&quot;">​</a></h2><p>The carrier&#39;s rules, not ours. Each of these has caused a support question:</p><ol><li><strong>A booking already has a seat.</strong> The carrier assigns one at creation, before payment, and seats a party together. There is never a seatless booking to fix.</li><li><strong>The seat map needs a paid booking.</strong> Marking an invoice paid on our side is not enough - if the carrier still considers the booking unpaid it will refuse, and the seat map stays unavailable until real payment reaches it.</li><li><strong>The window closes 72 hours before departure.</strong> A booking made inside that window cannot change seats at all, and no override exists on our side or theirs.</li><li><strong>Seats may change after ticketing.</strong> This surprises agents who know that passenger names cannot.</li><li><strong>A GROUP passenger must be named first.</strong> The rule is per passenger, so part of a group may be movable while the rest is not.</li><li><strong>An infant has no seat.</strong> It travels on the adult&#39;s, and shows as <code>passengerType: &quot;INF&quot;</code> in <code>currentSeats</code>. Asking to move one is refused with <code>400</code>. Move the adult and the infant follows.</li></ol><hr><h2 id="when-a-seat-can-be-moved-and-when-it-cannot" tabindex="-1">When a seat can be moved, and when it cannot <a class="header-anchor" href="#when-a-seat-can-be-moved-and-when-it-cannot" aria-label="Permalink to &quot;When a seat can be moved, and when it cannot&quot;">​</a></h2><p>Most support questions about seats are really questions about <em>where the booking is</em> in this sequence. The two shaded steps are the only ones in which a seat can move.</p>',14)),(a(),d(c,null,{default:s(()=>[l(n,{id:"mermaid-101",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20Ag%20as%20Agent%0A%20%20%20%20participant%20API%20as%20HHR%20API%0A%20%20%20%20participant%20W%20as%20Carrier%0A%0A%20%20%20%20Note%20over%20Ag%2CW%3A%20Booked%20-%20a%20seat%20exists%2C%20but%20nothing%20can%20move%20it%20yet%0A%20%20%20%20Ag-%3E%3EAPI%3A%20booking%20created%20for%20the%20customer%0A%20%20%20%20API-%3E%3EW%3A%20create%20reservation%0A%20%20%20%20W--%3E%3EAPI%3A%20reference%2C%20plus%20an%20assigned%20coach%20and%20seat%0A%20%20%20%20Note%20right%20of%20API%3A%20seat-map%20here%20answers%20400%20-%20not%20paid%0A%0A%20%20%20%20Note%20over%20Ag%2CW%3A%20Paid%20and%20ticketed%20-%20the%20window%20is%20now%20open%0A%20%20%20%20API-%3E%3EW%3A%20payment%20and%20ticket%20issue%0A%20%20%20%20W--%3E%3EAPI%3A%20e-ticket%20numbers%0A%0A%20%20%20%20rect%20rgb(220%2C%20233%2C%20228)%0A%20%20%20%20Note%20over%20Ag%2CW%3A%20Seat%20can%20move%2C%20until%2072h%20before%20departure%0A%20%20%20%20Ag-%3E%3EAPI%3A%20GET%20%2Fadmin%2Fota%2Fbookings%2F%7Bid%7D%2Fseat-map%0A%20%20%20%20API-%3E%3EW%3A%20read%20booking%2C%20then%20seat%20map%0A%20%20%20%20W--%3E%3EAPI%3A%20seats%20per%20segment%0A%20%20%20%20API--%3E%3EAg%3A%20map%20plus%20currentSeats%2C%20showing%20who%20sits%20where%0A%20%20%20%20Ag-%3E%3EAPI%3A%20PATCH%20%2Fadmin%2Fota%2Fbookings%2F%7Bid%7D%2Fseat%0A%20%20%20%20API-%3E%3EW%3A%20move%20one%20passenger%20to%20one%20seat%0A%20%20%20%20W--%3E%3EAPI%3A%20accepted%0A%20%20%20%20API-%3E%3EW%3A%20fresh%20read%0A%20%20%20%20W--%3E%3EAPI%3A%20the%20seats%20everyone%20now%20holds%0A%20%20%20%20API--%3E%3EAg%3A%20200%2C%20and%20the%20stored%20seat%20is%20refreshed%0A%20%20%20%20end%0A%0A%20%20%20%20Note%20over%20Ag%2CW%3A%20Inside%2072h%20of%20departure%20-%20closed%0A%20%20%20%20Ag-%3E%3EAPI%3A%20seat-map%20or%20seat%20change%0A%20%20%20%20API--%3E%3EAg%3A%20400%2C%20quoting%20the%20deadline%2C%20no%20carrier%20call%20made%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p><strong>Reading this as an agent</strong></p><ul><li><strong>&quot;The customer cannot see the seat map&quot; is almost always step 1 or the last step</strong>: the booking is not paid at the carrier, or the trip is inside 72 hours. Both answer <code>400</code> with a message written to be read out to the customer.</li><li><strong>A ticketed booking can still move a seat.</strong> That is the surprise in this diagram - passenger <em>names</em> cannot change after ticketing, seats can.</li><li><strong>The last step costs nothing upstream.</strong> The window is checked against the booking&#39;s own stored deadline, so a closed window is refused without asking the carrier.</li><li><strong>After a move, tell the customer to open their ticket link again.</strong> The document is rendered on demand and always carries the current seat; the copy in their inbox does not. Use <code>POST /api/v1/admin/ota/bookings/{id}/resend-ticket-confirmation-email</code> if they need a fresh copy delivered.</li></ul><hr><h2 id="get-the-seat-map" tabindex="-1">Get the seat map <a class="header-anchor" href="#get-the-seat-map" aria-label="Permalink to &quot;Get the seat map&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/admin/ota/bookings/{bookingId}/seat-map</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;admin-jwt&gt;</span></span></code></pre></div><p>Returns <code>segments</code>, each with <code>coaches</code> and their <code>seats</code>, plus <code>currentSeats</code>.</p><p><code>currentSeats</code> is the important one for support work: it is the only place that maps a passenger to a segment to a seat. The map marks a seat as taken without naming who holds it, so &quot;which seat is Mr X in&quot; can only be answered from <code>currentSeats</code>.</p><p>A seat is selectable only when <code>available</code> is <code>true</code>. That flag is an allow-list of one carrier value, because the carrier returns availability values its own documentation does not list, and treating an unknown value as free would offer a seat that cannot be taken.</p><hr><h2 id="change-a-seat" tabindex="-1">Change a seat <a class="header-anchor" href="#change-a-seat" aria-label="Permalink to &quot;Change a seat&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATCH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/admin/ota/bookings/{bookingId}/seat</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;admin-jwt&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;segmentRph&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;travelerRph&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;seatNumber&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;150&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>One seat per request. Moving a family means several requests, each of which can fail on its own.</li><li>Do not send a coach. The carrier resolves it from the seat number, and a move may cross coaches.</li><li>There is no cost, and no limit on how many times a seat may move inside the window.</li></ul><hr><h2 id="after-a-change-tell-the-customer-to-download-again" tabindex="-1">After a change: tell the customer to download again <a class="header-anchor" href="#after-a-change-tell-the-customer-to-download-again" aria-label="Permalink to &quot;After a change: tell the customer to download again&quot;">​</a></h2><p>The customer&#39;s existing ticket link keeps working and always renders the current seat, because the document is generated on demand and the e-ticket number does not change.</p><p>A ticket the customer already saved, or received as an email attachment, still shows the <strong>old</strong> seat. No new email is sent automatically. If the customer needs a fresh copy in their inbox, use the existing resend on the booking:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/admin/ota/bookings/{bookingId}/resend-ticket-confirmation-email</span></span></code></pre></div><hr><h2 id="stored-seat-data" tabindex="-1">Stored seat data <a class="header-anchor" href="#stored-seat-data" aria-label="Permalink to &quot;Stored seat data&quot;">​</a></h2><p>After a successful change the booking&#39;s stored seat and coach are refreshed from a fresh carrier read, so the booking detail and any manifest reflect the new seat.</p><p>Two details worth knowing when investigating a discrepancy:</p><ul><li>the refresh reads a <strong>fresh booking read</strong>, never the change response itself. That response carries seat details only for the passenger who moved, so using it would blank the stored seats of everyone else on the booking;</li><li>the carrier rewrites its internal provider ticket number on every seat change. The e-ticket number, which is what the customer sees, does not change.</li></ul><hr><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>400</code></td><td>Not paid yet, window closed, passenger unnamed, or the seat number does not exist</td></tr><tr><td><code>403</code></td><td>Missing <code>bookings:read</code> or <code>bookings:modify</code></td></tr><tr><td><code>404</code></td><td>Booking not found</td></tr><tr><td><code>409</code></td><td>The seat was taken between loading the map and submitting</td></tr><tr><td><code>502</code></td><td>Carrier refused for a reason we do not recognise. The detail is logged with a correlation id</td></tr></tbody></table><p>A refusal raised by our own request checks - a segment or traveller that is not on the booking, a missing seat number - is a <code>400</code> carrying that reason verbatim, never a <code>502</code>. <code>502</code> means the carrier answered something the service has no mapping for; the log line holds the carrier&#39;s own <code>detail</code> and its correlation id:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[OTA_AirSeatMapRQ] failed {&quot;bookingRef&quot;:&quot;NK6GK3&quot;,&quot;status&quot;:400,&quot;code&quot;:&quot;448&quot;,</span></span>
<span class="line"><span> &quot;detail&quot;:&quot;SeatMap process failure: [Segment JXD-MKX 2026-09-11] Seat selection is not allowed</span></span>
<span class="line"><span> before payment is completed&quot;,&quot;correlationId&quot;:&quot;7a8fdd00-27d2-49a0-a429-795245d2fecf&quot;}</span></span></code></pre></div><p>That particular one <strong>is</strong> mapped, and reaches the caller as <code>400 Seats can only be chosen once the booking has been paid.</code> The example shows what to look for in the log when an unmapped one appears.</p><p><strong>The carrier&#39;s <code>code</code> is not a reliable discriminator and neither is its <code>title</code>.</strong> Three different codes were captured on the same endpoint within one session - <code>448</code> on the payment refusal, <code>9999</code> on a seat somebody else holds (<em>&quot;the seat &lt;id&gt; / &lt;from&gt; / &lt;to&gt; is not available&quot;</em>), and <code>450</code> on a seat number that does not exist (<em>&quot;Space id not found for seat 9999 on segment 1&quot;</em>). The <code>detail</code> string is the only part that identifies the cause, which is why the mapping matches on it.</p><h2 id="checking-a-refusal-without-spending-a-carrier-call" tabindex="-1">Checking a refusal without spending a carrier call <a class="header-anchor" href="#checking-a-refusal-without-spending-a-carrier-call" aria-label="Permalink to &quot;Checking a refusal without spending a carrier call&quot;">​</a></h2><p>The window check runs locally, off the booking&#39;s stored time limits, so a closed window is refused before any upstream request. Measured on a booking whose window closed on 15 July:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/admin/ota/bookings/{id}/seat-map</span></span>
<span class="line"><span>400 {&quot;message&quot;:&quot;Seat changes are no longer possible for this booking.</span></span>
<span class="line"><span>     The window closed at 15 Jul 2026, 16:30 WIB.&quot;}</span></span></code></pre></div><p>The deadline is rendered in WIB. Zero <code>OTA_AirSeatMapRQ</code> calls were made for that request.</p>`,33))])}const y=o(p,[["render",g]]);export{f as __pageData,y as default};
